<script setup>
import {ref,computed,onMounted,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {api,ui,mutate,notify} from '../lib/api.js';import {money,dateLabel,today} from '../lib/format.js';import PageTitle from '../components/PageTitle.vue';import Icon from '../components/Icon.vue';import Badge from '../components/Badge.vue';import EmptyState from '../components/EmptyState.vue';import Modal from '../components/Modal.vue';
const route=useRoute(),router=useRouter(),cursor=ref(new Date(today()+'T12:00:00Z')),mode=ref(route.query.mode||'month'),type=ref(route.query.type||'all'),status=ref(''),selected=ref(today()),data=ref({events:[],archive:[]}),error=ref('');
const year=computed(()=>cursor.value.getUTCFullYear()),month=computed(()=>cursor.value.getUTCMonth());
const heading=computed(()=>mode.value==='year'||mode.value==='archive'?String(year.value):mode.value==='day'?dateLabel(selected.value):cursor.value.toLocaleDateString('fr-FR',{month:'long',year:'numeric',timeZone:'UTC'}));
async function load(){try{error.value='';data.value=await api(`/calendar?from=${year.value}-01-01&to=${year.value}-12-31&type=${type.value}&status=${status.value}`);}catch(e){error.value=e.message;}}
onMounted(load);watch([year,type,status,()=>ui.revision],load);
const events=computed(()=>['invoices','expenses'].includes(type.value)?data.value.archive:data.value.events);
const cells=computed(()=>{const first=new Date(Date.UTC(year.value,month.value,1,12)),offset=(first.getUTCDay()+6)%7;first.setUTCDate(1-offset);return Array.from({length:42},(_,i)=>{const d=new Date(first);d.setUTCDate(d.getUTCDate()+i);const date=d.toISOString().slice(0,10);return {date,day:d.getUTCDate(),other:d.getUTCMonth()!==month.value,events:events.value.filter(e=>e.date===date)};});});
const groups=computed(()=>[...new Set(data.value.archive.map(e=>e.date.slice(0,7)))].map(key=>({key,title:dateLabel(key+'-01').replace(/^01 /,''),rows:data.value.archive.filter(e=>e.date.startsWith(key))})));
const daily=computed(()=>events.value.filter(e=>e.date===selected.value));
function move(amount){const d=new Date(cursor.value);if(mode.value==='year'||mode.value==='archive')d.setUTCFullYear(d.getUTCFullYear()+amount);else if(mode.value==='day'){d.setUTCDate(d.getUTCDate()+amount);selected.value=d.toISOString().slice(0,10);}else{d.setUTCDate(1);d.setUTCMonth(d.getUTCMonth()+amount);}cursor.value=d;}
function pickDay(date){selected.value=date;cursor.value=new Date(date+'T12:00:00Z');mode.value='day';}
function open(e){if(e.type==='manual'){editEntry(e);return;}if(e.type==='booking')return;router.push(e.type==='subscriptions'?'/finances':`/${e.type}/${e.entityId||e.id}`);}
const formOpen=ref(false),saving=ref(false),editingId=ref(null),formError=ref('');
const blank=()=>({title:'',date:selected.value||today(),time:'',endTime:'',detail:''});
const form=ref(blank());
function addEntry(){editingId.value=null;form.value=blank();formError.value='';formOpen.value=true;}
function editEntry(e){editingId.value=e.entityId;form.value={title:e.title,date:e.date,time:e.time||'',endTime:e.endTime||'',detail:e.detail||''};formError.value='';formOpen.value=true;}
async function saveEntry(){try{saving.value=true;formError.value='';const path=editingId.value?`/calendar-entries/${editingId.value}`:'/calendar-entries';await mutate(path,editingId.value?'PATCH':'POST',form.value,editingId.value?'Entrée modifiée.':'Entrée ajoutée.');formOpen.value=false;}catch(err){formError.value=err.message;}finally{saving.value=false;}}
async function removeEntry(e){if(!confirm('Supprimer cette entrée personnelle ?'))return;try{await mutate(`/calendar-entries/${e.entityId}`,'DELETE',undefined,'Entrée supprimée.');}catch(err){notify(err.message,'error');}}
</script>
<template><PageTitle number="09" title="LE CALENDRIER" subtitle="Chaque échéance, au bon endroit."><button class="btn" @click="cursor=new Date(today()+'T12:00:00Z');selected=today()">Aujourd’hui</button><button class="btn primary" @click="addEntry"><Icon name="Plus"/>Ajouter</button></PageTitle><div class="calendar-toolbar"><div><button class="icon-button outlined" @click="move(-1)" aria-label="Période précédente"><Icon name="ChevronLeft"/></button><button class="icon-button outlined" @click="move(1)" aria-label="Période suivante"><Icon name="ChevronRight"/></button><h2>{{heading}}</h2></div><div><select v-model="type" aria-label="Type d’événement"><option value="all">Toutes les échéances</option><option value="quotes">Devis</option><option value="projects">Projets</option><option value="invoices">Factures clients / revenus</option><option value="expenses">Fournisseurs / dépenses</option><option value="subscriptions">Abonnements</option><option value="booking">RDV Cal.com</option><option value="manual">Perso</option></select><div class="segmented"><button v-for="[v,l] in [['day','JOUR'],['month','MOIS'],['year','ANNÉE'],['archive','ARCHIVES']]" :key="v" :class="{selected:mode===v}" @click="mode=v">{{l}}</button></div></div></div><p v-if="error" class="form-error">{{error}}</p><div v-if="mode==='month'" class="calendar-container"><div class="calendar-grid"><div v-for="day in ['LUN','MAR','MER','JEU','VEN','SAM','DIM']" :key="day" class="weekday">{{day}}</div><div v-for="cell in cells" :key="cell.date" class="calendar-cell" :class="{other:cell.other,today:cell.date===today()}"><button class="day-number" @click="pickDay(cell.date)" :aria-label="dateLabel(cell.date)">{{cell.day}}</button><button v-for="e in cell.events.slice(0,3)" :key="e.id" class="calendar-event" :class="e.type" @click="open(e)" :title="e.title+' · '+e.detail">{{e.time?e.time+' · ':''}}{{e.title}}</button><button v-if="cell.events.length>3" class="text-button" style="font-size:11px" @click="pickDay(cell.date)">+ {{cell.events.length-3}} autres</button></div></div></div><div v-else-if="mode==='year'" class="year-grid"><button v-for="n in 12" :key="n" class="month-card" @click="cursor=new Date(Date.UTC(year,n-1,1,12));mode='month'"><span class="eyebrow accent">{{String(n).padStart(2,'0')}}</span><h3>{{new Date(Date.UTC(year,n-1,1)).toLocaleDateString('fr-FR',{month:'long',timeZone:'UTC'})}}</h3><p>{{events.filter(e=>Number(e.date.slice(5,7))===n).length}} événements</p></button></div><template v-else-if="mode==='day'"><label style="max-width:230px;margin-bottom:24px">Choisir un jour<input v-model="selected" type="date" @change="cursor=new Date(selected+'T12:00:00Z')"></label><div v-for="e in daily" :key="e.id" class="document-row"><Icon :name="e.time?'Clock':'CalendarDays'"/><div><strong>{{e.time?e.time+(e.endTime?'–'+e.endTime:'')+' · ':''}}{{e.title}}</strong><small>{{e.detail||(e.type==='booking'?'Réservation Cal.com':'')}}</small></div><Badge v-if="e.type==='booking'" :status="e.status==='cancelled'?'cancelled':'booking'"/><Badge v-else-if="e.type==='manual'" status="manual"/><span v-if="e.amountCents" class="mono">{{money(e.amountCents,true)}}</span><template v-if="e.editable"><button class="icon-button" @click="editEntry(e)" aria-label="Modifier l’entrée"><Icon name="Pencil"/></button><button class="icon-button" @click="removeEntry(e)" aria-label="Supprimer l’entrée"><Icon name="Trash2"/></button></template><button v-else-if="e.type!=='booking'" class="icon-button" @click="open(e)" aria-label="Ouvrir le dossier"><Icon name="ArrowUpRight"/></button></div><EmptyState v-if="!daily.length" title="Une journée sans échéance." description="Les prochaines dates figurent dans la vue mensuelle."/></template><template v-else><div class="toolbar"><span class="muted">Classement par date de facture</span><select v-model="status" aria-label="Statut du paiement"><option value="">Payé et non payé</option><option value="paid">Payé</option><option value="unpaid">Non payé</option></select></div><section v-for="group in groups" :key="group.key" class="archive-group"><h2>{{group.title}}</h2><div class="panel table-scroll"><table><thead><tr><th>DATE</th><th>CLIENT / FOURNISSEUR</th><th>RÉFÉRENCE / CATÉGORIE</th><th>TYPE</th><th>MONTANT TTC</th><th>STATUT</th><th></th></tr></thead><tbody><tr v-for="e in group.rows" :key="e.type+e.id"><td>{{dateLabel(e.date,true)}}</td><td>{{e.title}}</td><td>{{e.detail}}</td><td>{{e.type==='expenses'?'Dépense':'Facture client'}}</td><td class="mono">{{money(e.amountCents,true)}}</td><td><Badge :status="e.status"/></td><td><button class="icon-button" @click="open(e)" aria-label="Ouvrir la facture"><Icon name="ArrowUpRight"/></button></td></tr></tbody></table></div></section><EmptyState v-if="!groups.length" title="Aucune facture sur cette période." description="Changez l’année ou le filtre."/></template><Modal :open="formOpen" :title="editingId?'Modifier l’entrée':'Nouvelle entrée'" @close="formOpen=false"><form @submit.prevent="saveEntry"><div class="form-grid"><label style="grid-column:1/-1">Titre<input v-model="form.title" required maxlength="200" placeholder="Rendez-vous, rappel, note…"></label><label>Date<input v-model="form.date" type="date" required></label><label>Heure (optionnel)<input v-model="form.time" type="time"></label><label>Heure de fin (optionnel)<input v-model="form.endTime" type="time"></label></div><label style="margin-top:18px;display:block">Note (optionnel)<textarea v-model="form.detail" rows="3" maxlength="10000"></textarea></label><p v-if="formError" class="form-error">{{formError}}</p><div class="form-actions"><button type="button" class="btn" @click="formOpen=false">Annuler</button><button type="submit" class="btn primary" :disabled="saving">{{editingId?'Enregistrer':'Ajouter'}}</button></div></form></Modal></template>
